def parse_size(line, dest):
    size = None

    if dest == 'buffered':
        match = re.search(r'logging buffered(?: (\d+))?(?: [a-z]+)?', line, re.M)
        if match:
            if match.group(1) is not None:
                size = match.group(1)
            else:
                size = "4096"

    return size


def parse_name(line, dest):
    if dest == 'host':
        match = re.search(r'logging host (\S+)', line, re.M)
        if match:
            name = match.group(1)
    else:
        name = None

    return name


def parse_level(line, dest):
    level_group = ('emergencies', 'alerts', 'critical', 'errors', 'warnings',
                   'notifications', 'informational', 'debugging')

    if dest == 'host':
        level = 'debugging'

    else:
        if dest == 'buffered':
            match = re.search(r'logging buffered(?: \d+)?(?: ([a-z]+))?', line, re.M)
        else:
            match = re.search(r'logging {0} (\S+)'.format(dest), line, re.M)

        if match and match.group(1) in level_group:
            level = match.group(1)
        else:
            level = 'debugging'

    return level


